int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("oracle required");std::ifstream in(argv[1],std::ios::binary);for(unsigned present=0;present<2;++present)for(uint32_t old=0;old<16;++old)for(uint32_t choice=0;choice<17;++choice){uint32_t index=choice==16?0xffffffffu:choice,cached=0xdeadbeefu;std::vector<uint32_t> v;for(uint32_t i=0;i<old;++i)v.push_back(0x3f000000u+i);recoveredFlexControllerIndexBindingCandidate(cached,index,present?&v:nullptr);auto nativeIndex=read(in),size=read(in),append=read(in),remove=read(in),resolves=read(in);if(cached!=nativeIndex||size!=v.size())throw std::runtime_error("index/count mismatch");if(append!=(size>old?size-old:0)||remove!=(old>size?old-size:0))throw std::runtime_error("resize count mismatch");auto expectedResolves=!present?1u:(index<old?2u:3u);if(resolves!=expectedResolves)throw std::runtime_error("resolution count mismatch");for(auto x:v)if(x!=read(in))throw std::runtime_error("payload mismatch");}if(in.peek()!=EOF)throw std::runtime_error("trailing oracle");std::cout<<"x64 flex index: 544 native comparisons passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
